package com.example.takura.enquiries.controller;
import com.example.takura.enquiries.application.EnquiryService;import com.example.takura.enquiries.application.EnquiryService.Request;import com.example.takura.enquiries.application.LeadOperationsService;import com.example.takura.enquiries.application.LeadOperationsService.*;
import com.example.takura.identity.controller.StaffRequestPrincipal;import com.example.takura.identity.domain.StaffPrincipal;import jakarta.servlet.http.HttpServletRequest;import java.util.UUID;
import java.time.Instant;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1") public class EnquiryController{
 private final EnquiryService service;private final LeadOperationsService leads;EnquiryController(EnquiryService service,LeadOperationsService leads){this.service=service;this.leads=leads;}
 @PostMapping("/enquiries") ResponseEntity<?> create(@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="X-Correlation-ID",required=false)String correlation,@RequestBody Request body,HttpServletRequest request){String c=correlation==null||correlation.isBlank()?UUID.randomUUID().toString():correlation;return ResponseEntity.status(HttpStatus.CREATED).header("X-Correlation-ID",c).body(service.create(key,body,request.getRemoteAddr(),c));}
 @GetMapping("/admin/dashboard") Object dashboard(@StaffRequestPrincipal StaffPrincipal p){return leads.dashboard(p);}
 @GetMapping("/admin/enquiries") Object list(@StaffRequestPrincipal StaffPrincipal p,@RequestParam(required=false)String state,@RequestParam(required=false)String team,@RequestParam(required=false)UUID owner,@RequestParam(required=false)String service,@RequestParam(required=false)String area,@RequestParam(required=false)Boolean unassigned,@RequestParam(required=false)Boolean overdue,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to,@RequestParam(required=false)UUID cursor,@RequestParam(defaultValue="25",name="page_size")int size){return leads.list(p,new Filter(state,team,owner,service,area,unassigned,overdue,from,to,cursor,size));}
 @GetMapping("/admin/enquiries/count") Object count(@StaffRequestPrincipal StaffPrincipal p){return leads.dashboard(p);}
 @GetMapping("/admin/enquiries/export") ResponseEntity<String> export(@StaffRequestPrincipal StaffPrincipal p,@RequestParam(required=false)String state,@RequestParam(required=false)String team,@RequestParam(required=false)String area){return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=lead-export.csv").body(leads.exportCsv(p,new Filter(state,team,null,null,area,null,null,null,null,null,100)));}
 @GetMapping("/admin/enquiries/{id}") ResponseEntity<?> detail(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id){var result=leads.detail(p,id);return ResponseEntity.ok().eTag(q(result.enquiry().revision())).body(result);}
 @PostMapping("/admin/enquiries/{id}/assignment") ResponseEntity<Void> assign(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Assignment body){return etag(leads.assign(p,id,pre(match),body));}
 @PostMapping("/admin/enquiries/{id}/activities") ResponseEntity<?> activity(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ActivityCommand body){long revision=pre(match);var value=leads.addActivity(p,id,revision,body);return ResponseEntity.status(201).eTag(q(revision+1)).body(value);}
 @PostMapping("/admin/enquiries/{id}/tasks") ResponseEntity<?> task(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestBody TaskCommand body){return ResponseEntity.status(201).body(leads.createTask(p,id,body));}
 @PatchMapping("/admin/enquiries/{id}/tasks/{task}") ResponseEntity<Void> taskUpdate(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@PathVariable UUID task,@RequestHeader(value="If-Match",required=false)String match,@RequestBody TaskUpdate body){return etag(leads.updateTask(p,id,task,pre(match),body));}
 @PostMapping("/admin/enquiries/{id}/transition") ResponseEntity<Void> transition(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestBody Transition body){return etag(leads.transition(p,id,pre(match),body));}
 @PostMapping("/admin/enquiries/{id}/evidence") ResponseEntity<Void> evidence(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestBody EvidenceCommand body){return etag(leads.recordEvidence(p,id,pre(match),body));}
 @PostMapping("/admin/enquiries/{id}/assessments") ResponseEntity<?> assessment(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestBody AssessmentCommand body){return ResponseEntity.status(201).body(leads.createAssessment(p,id,body));}
 @PatchMapping("/admin/enquiries/{id}/assessments/{assessment}") ResponseEntity<Void> assessmentUpdate(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@PathVariable UUID assessment,@RequestHeader(value="If-Match",required=false)String match,@RequestBody AssessmentUpdate body){return etag(leads.updateAssessment(p,id,assessment,pre(match),body));}
 @PutMapping("/admin/enquiries/{id}/cutting-review") ResponseEntity<Void> cutting(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String match,@RequestBody CuttingReview body){return etag(leads.reviewCutting(p,id,pre(match),body));}
 @PostMapping("/admin/enquiries/{id}/production-signoff") ResponseEntity<Void> signoff(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestBody ProductionSignoff body){leads.productionSignoff(p,id,body);return ResponseEntity.noContent().build();}
 @GetMapping("/admin/audit") Object audit(@StaffRequestPrincipal StaffPrincipal p,@RequestParam(defaultValue="25")int limit){return leads.audit(p,limit);}
 @GetMapping("/admin/notifications") Object notifications(@StaffRequestPrincipal StaffPrincipal p,@RequestParam(defaultValue="25")int limit){return leads.notifications(p,limit);}
 @PostMapping("/admin/notifications/{id}/retry") ResponseEntity<Void> retry(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id){leads.retryNotification(p,id);return ResponseEntity.noContent().build();}
 private static ResponseEntity<Void> etag(long value){return ResponseEntity.noContent().eTag(q(value)).build();}private static String q(long value){return "\""+value+"\"";}private static long pre(String value){if(value==null)throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match is required");try{return Long.parseLong(value.replace("\"",""));}catch(NumberFormatException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"If-Match is invalid");}}
}
